INSERT INTO `recruitment` VALUES ('08e9c88b-bcd2-4d6f-93bd-9204d2f4caf4','a1d85342-7484-4c7b-9774-aeea64296576','PUBLISHED','Nhân Viên Học Việc Kỹ Thuật ( Tiếng Trung)','Nhan-Vien-Hoc-Viec-Ky-Thuat-(-Tieng-Trung)','Số 2 Láng Hạ - Phường Thành Công - Quận Ba Đình - TP. Hà Nội','<ol><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Tham gia vào quá trình phân tích, thiết kế và triển khai các giải pháp kỹ thuật.</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Hỗ trợ giám sát và thực hiện các nhiệm vụ kiểm tra, bảo trì và sửa chữa các hệ thống kỹ thuật.</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Xử lý các sự cố kỹ thuật và đưa ra các giải pháp khắc phục.</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Tham gia vào việc xây dựng và duy trì cơ sở dữ liệu công nghệ.</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Đảm bảo tuân thủ các quy định an toàn và quy trình làm việc của công ty.</span></li></ol><p></p>','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">1. </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Trình độ học vấn</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">: Tốt nghiệp Cao đẳng trở lên, đọc được bản vẽ 3D/2D, thành thạo tiếng Trung, thành thạo vi tính văn phòng</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">2. </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Kinh nghiệm làm việc</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">: Ưu tiên ứng viên có kinh nghiệm làm việc liên quan đến công ty sản xuất, đặc biệt có kinh nghiệm về sản phẩm cao su, silicone，không có kinh ngiệm sẽ được đào tạo</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">3. </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Yêu cầu về kỹ năng</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\"> ọc hiểu được bản vẽ 3D/2D của sản phẩm và hiểu được quy trình sản phẩm.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">4. </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Khả năng học tập</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">: Có khả năng học hỏi nhanh để nhanh chóng nắm vững các kiến ​​thức kỹ thuật mới</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">5. </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Khả năng thích ứng</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">: Có khả năng chịu được áp lực cao, chịu khó, hợp tác làm thêm giờ, đi công tác và tuân thủ yêu cầu của cấp trên</span></p><p></p>','01','SUPPLY_MANPOWER','FULL_TIME','2024-08-27 18:48:57','2024-08-30 10:00:00',15,30,'2024-08-28 01:50:28','2024-08-28 01:59:35','a1d85342-7484-4c7b-9774-aeea64296576','ea1e875b-104b-49a5-a2e2-061a540eca3a'),('10f2ed81-a526-4cfa-ae9c-9474641c09f4','a1d85342-7484-4c7b-9774-aeea64296576','PENDING','Phó Phòng Hàng Hải - Kỹ Thuật Phụ Trách Kỹ Thuật Vật Tư','Pho-Phong-Hang-Hai---Ky-Thuat-Phu-Trach-Ky-Thuat-Vat-Tu','TP.HCM, 52-54 Trương Văn Bang, Phường Bình Trưng Tây, Thủ Đức','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Hỗ trợ Trưởng phòng HH-KT trong công tác mua sắm vật tư.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Hỗ trợ, tham mưu cho TP. HH-KT trong công tác quản lý phòng, thay thế Trưởng phòng khi được uỷ quyền.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Đại diện cho P. HH-KT làm việc với BCH tàu để phổ biến hoặc trực tiếp chỉ đạo công tác sửa chữa, khắc phục sự cố tại hiện trường trong trường hợp Trưởng phòng không có mặt.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Theo dõi tình trạng kỹ thuật của toàn bộ đội tàu, hỗ trợ CVKT, KSĐ-ĐT BCH khi cần.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Hỗ trợ và đảm nhận công việc của CVKT khi cần thiết.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Hỗ trợ, đào tạo CVKT cũng như các sỹ quan quản lý trên tàu.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Phụ trách mua sắm Vật tư của phòng và các dự án theo chỉ đạo của Ban điều hành dự án.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">-    Chỉ đạo các chuyên viên HH-KT mua sắm phụ tùng vật tư được phân công.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Ủy quyền khi vắng mặt (người thay thế): chuyên viên KT-VT được chỉ định. </span></p>','<p><span style=\"background-color: rgb(255, 255, 255); color: black;\">- Tốt nghiệp đại học/cao đẳng một trong các chuyên ngành kỹ thuật.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: black;\">-  Có kinh nghiệm ở các vị trí quản lý kỹ thuật đội tàu, tối thiểu 5 năm.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: black;\">-  Có kinh nghiệm chuyên sâu ở ít nhất một trong các lĩnh vực vận hành, đóng mới, sửa chữa máy/điện tàu thủy, quản lý vật tư, cơ - điện tử, công nghệ thông tin.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: black;\">- Sử dụng thành thạo các phần mềm văn phòng.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: black;\">- Có kỹ năng giao tiếp bằng tiếng Anh chuyên ngành kỹ thuật tốt.</span></p><p></p>','01','REAL_ESTATE_LEASE','FULL_TIME','2024-08-27 11:44:51','2024-08-30 03:00:00',25,30,'2024-08-28 01:48:41','2024-08-28 01:48:41','a1d85342-7484-4c7b-9774-aeea64296576','system'),('48a4e044-40b2-42d1-86fc-b82a2cec7339','a1d85342-7484-4c7b-9774-aeea64296576','PUBLISHED','Trợ Giảng Tiếng Anh','Tro-Giang-Tieng-Anh','Hà Nội, Học viện Bưu Chính Viễn Thông, Hà Đông','<ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Hỗ trợ Giảng viên thực hiện kế hoạch giảng dạy tại Học viện</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Trả lời, giải đáp các vấn đề kiến thức chuyên ngành theo nhiệm vụ đã được phân công</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Kiểm soát chuyên cần học tập của học viên</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Chấm, chữa bài tập/ Nhập nhận xét bài kiểm tra hàng tháng hoặc bài thi</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Thực hiện công việc nhập điểm, báo cáo học tập hàng tháng/ Cuối kỳ học (nếu có)</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Báo cáo và giải quyết các vấn đề phát sinh</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Tham gia các chương trình đào tạo nâng cao chuyên môn, bổ sung kỹ năng sư phạm, dẫn dắt đội nhóm</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Mục tiêu kỳ vọng sau 1 năm có thể đảm nhiệm vai trò Giảng dạy chính</span></li></ul><p></p>','<ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(255, 0, 0);\">Làm việc từ Thứ 2 đến Thứ 6: 8h00 - 17h30</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Ưu tiên có ít nhất 1 năm làm lập trình viên (Java hoặc Javascript)</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Yêu thích truyền đạt kiến thức, đào tạo</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Thái độ cầu tiến, chủ động, biết lắng nghe, trách nhiệm với công việc</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Có khả năng giao tiếp, thuyết phục, xử lý tình huống tốt</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Có khả năng làm việc độc lập và theo nhóm</span></li></ul><p></p>','01','PACKAGING_PRINTING_STICKERS','FULL_TIME','2024-08-27 19:42:38','2024-08-30 10:00:00',5,8,'2024-07-28 02:43:31','2024-08-28 02:47:03','a1d85342-7484-4c7b-9774-aeea64296576','ea1e875b-104b-49a5-a2e2-061a540eca3a'),('556e578c-af5f-4dfc-9b8c-180d655ad688','74c9ed65-76c1-4945-a024-1ac5a937caac','PUBLISHED','Chuyên Viên Đào Tạo Nội Bộ (Yêu Cầu 03 Năm Kinh Nghiệm Đào Tạo)','Chuyen-Vien-Đao-Tao-Noi-Bo-(Yeu-Cau-03-Nam-Kinh-Nghiem-Đao-Tao)','Hà Nội, Tầng 3 Tòa nhà LILAMA Số 124 Minh Khai, Hai Bà Trưng, Hà Nội., Hai Bà Trưng','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Địa điểm làm việc: Tầng 3 Tòa nhà LILAMA Số 124 Minh Khai, Hai Bà Trưng, Hà Nội.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Thời gian làm việc: Từ 8h00 đến 17h30 từ thứ 2 đến sáng thứ 7, nghỉ các chiều T7 và CN hàng tuần.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\"> </span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">1. Nghiên cứu, xây dựng nội dung đào tạo</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Nghiên cứu, tìm hiểu, thống kê các nội dung đào tạo, bao gồm:</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Nghiên cứu, tìm hiểu nhu cầu người học;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Nghiên cứu nội dung, cấu trúc bài giảng, phương pháp tiếp cận giảng dạy theo đối tượng người học; thực hiện đưa ứng dụng về phương tiện, công cụ giảng dạy phù hợp thực tiễn;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Tìm hiểu các mô hình &amp; xu hướng đào tạo nhằm đảm bảo hiệu quả, tiết kiệm thời gian, chi phí.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Thực hiện triển khai các hoạt động đánh giá và đề xuất xây dựng các nội dung đào tạo mang tính ứng dụng cao, gắn với hiện trạng, nhu cầu của doanh nghiệp.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Xây dựng nội dung, hướng dẫn, để người học được tiệm cận các phương pháp học và dễ tiếp nhận kiến thức.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Phối hợp với phòng/ban/bộ phận trong nội bộ công ty hoặc kết hợp đối tác bên ngoài lên các nội dụng đào tạo, đáp ứng nhu cầu học tập, phát triển.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">2. Triển khai đào tạo &amp; tái đào tạo</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Thực hiện các hoạt động sát hạch, kiểm tra, đánh giá sàng lọc đối tượng đào tạo, chất lượng trong và sau đào tạo;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Trực tiếp giảng dạy hoặc thực hiện công tác trợ giảng theo phân công nhiệm vụ;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Đồng bộ chất lượng đào tạo theo phân loại đối tượng học viên, vị trí công việc;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Xây dựng các thang điểm, khung giám sát, tiêu chuẩn đạt theo nội dung đào tạo, huấn luyện.</span></p><p></p>','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Tốt nghiệp Đại học trở lên; ưu tiên các ngành Sư phạm, Quản trị nhân lực...</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Kỹ năng văn phòng: sử dụng tốt phần mềm Microsoft Office</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Có khả năng phân tích tâm lý, hành vi con người;</span></p><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Có kinh nghiệm xây dựng bài giảng và phương pháp giảng dạy.</strong></p><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Có tối thiểu 03 năm làm đào tạo nội bộ tại các doanh nghiệp.</strong></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Ngoại hình sáng;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Cẩn thận, cầu thị, tôn trọng;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">- Nhiệt huyết, thân thiện, tinh thần trách nhiệm công việc cao</span></p>','01','PACKAGING_PRINTING_STICKERS','PART_TIME','2024-08-27 19:36:26','2024-08-30 10:00:00',7,15,'2024-08-28 02:38:14','2024-08-28 02:41:02','74c9ed65-76c1-4945-a024-1ac5a937caac','ea1e875b-104b-49a5-a2e2-061a540eca3a'),('6de00316-6afe-4604-a90e-ca9c284472a5','3b1d1224-1d7a-43e5-ba3e-87e963c0e1d7','PUBLISHED','IT Engineer','IT-Engineer','Số 22 Vsip II-A, Đường số 23, Khu Công Nghiệp Việt Nam-Singapore II-A, Phường Vĩnh Tân, Thành phố Tân Uyên, Tỉnh Bình Dương, Việt Nam','<ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(65, 64, 69);\">Install, configure, integrate, maintain, diagnose, debug, upgrade and training of Computer Operating Systems such as UNIX, Linux, Windows, Windows NT, and TCP/IP networking.</span></li><li><em style=\"background-color: rgb(255, 255, 255); color: blue;\">Cài đặt, cấu hình, tích hợp, bảo trì, chẩn 